/// <summary>
/// Service class to send sales order cancellation business event as a batch
/// </summary>
class METSendSalesOrderCancelledBusinessEventService extends SysOperationServiceBase
{

}

Method.Source:
    /// <summary>
    /// Process the sales order cancellations.
    /// </summary>
    public void process()
    {
        SalesLine      salesLine;
        METSalesLine   metSalesLine;

        try
        {
            select firstonly DataAreaId from salesLine 
                join RecId from metsalesLine
                    where metSalesLine.SalesLine == salesLine.RecId
                       && salesLine.SalesStatus == SalesStatus::Canceled
                       && metSalesLine.IntegrationStatus  == METIntegrationStatus::ReadyToSend;
            {
                if(BusinessEventsConfigurationReader::isBusinessEventEnabled(classStr(METSalesOrderCancelledBusinessEvent)))
                {
                    METSalesOrderCancelledBusinessEvent::newFromSalesCancellation(salesLine).send();
                }
                else
                {
                    throw error("@MET:SOCancellationBusinessEventNotEnabled");
                }
            }
        }
        catch(Exception::Error)
        {
            error("@MET:SOCancellationBusinessEventError");
        }
    }
